/// <summary>
/// MPJ_5012_RebateProcess
/// Class <c>METGUPPRiceDiscPricingRulePreviewIncludeFormControl_Extension</c>
/// </summary>
[ExtensionOf(formControlStr(GUPPRiceDiscPricingRulePreview, METIncludeForPaymentBtn))]
internal final class METGUPPRiceDiscPricingRulePreviewIncludeFormControl_Extension
{
}

Method.Source:
    /// <summary>
    /// Including the selected products from payment
    /// </summary>
    public void clicked()
    {
        next clicked();

        MultiSelectionHelper    selectionHelper = MultiSelectionHelper::construct();
        InventTable             inventTableInclusion;
        
        FormDataSource  inventTable_ds  = this.formRun().dataSource(formDataSourceStr(GUPPriceDiscPricingRulePreview, InventTable)) as FormDataSource;
        selectionHelper.parmDatasource(InventTable_ds);
        inventTableInclusion = selectionHelper.getFirst();
        GUPRefRecId ruleId = this.getRuleId(element.args());

        ttsbegin;
        while (inventTableInclusion)
        {
            METExcludeForPaymentProducts    excludeForPaymentProducts;
            delete_from excludeForPaymentProducts
                where excludeForPaymentProducts.RuleId == ruleId && excludeForPaymentProducts.ItemId == inventTableInclusion.ItemId;
            inventTableInclusion = selectionHelper.getNext();
        }
        ttscommit;
    
        InventTable_ds.executeQuery();

    }

public GUPRefRecId getRuleId(Args    _args)
{
    GUPPricingRulePreviewTrans pricingRulePreviewTrans = _args.record() as GUPPricingRulePreviewTrans;
    return GUPPricingRuleCopy::findByRuleId(pricingRulePreviewTrans.PricingRuleLine).RuleId;
}
